<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {Image,Check,KeyRound} from 'lucide-vue-next'
import {worldApi} from './api'
import {useRequestScope} from '../platform/request-scope'
const source=ref('personal')
const capture=useRequestScope(),enabled=ref(false),hasKey=ref(false),loaded=ref(false),editing=ref(false),key=ref(''),limit=ref(50),busy=ref(false),error=ref('');let generation=0
async function load(){const scope=capture();try{const result=await worldApi<{enabled:boolean;hasKey:boolean;dailyLimit:number;source?:string}>('/scene-profile');if(scope.valid()){loaded.value=true;source.value=result.source||'personal';enabled.value=result.enabled;hasKey.value=result.hasKey;limit.value=result.dailyLimit}}catch{/* Older/offline servers keep the existing text settings usable. */}}
async function save(){const scope=capture(),version=++generation;busy.value=true;error.value='';try{await worldApi('/scene-profile',key.value?{method:'PUT',body:{key:key.value,dailyLimit:limit.value}}:{method:'PATCH',body:{enabled:true,dailyLimit:limit.value}});if(scope.valid()&&version===generation){key.value='';editing.value=false;enabled.value=true;hasKey.value=true;await load()}}catch(e){if(scope.valid()&&version===generation)error.value=(e as Error).message}finally{if(scope.valid()&&version===generation)busy.value=false}}
async function toggle(){const scope=capture(),version=++generation;busy.value=true;try{const result=await worldApi<{enabled:boolean}>('/scene-profile',{method:'PATCH',body:{enabled:!enabled.value}});if(scope.valid()&&version===generation)enabled.value=result.enabled}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
onMounted(load);onUnmounted(()=>{generation++;key.value=''})
</script>
<template><article v-if="loaded" class="list-item scene-model-settings"><div class="row between"><div><h2><Image :size="19"/> Agnes 场景图像 <span v-if="enabled" class="badge"><Check :size="13"/>已配置</span></h2><p>Agnes Image 2.5 Flash · 360° 场景</p><small v-if="hasKey" class="muted">{{source==='platform'?'平台提供 · 无需填写密钥':'个人通道'}} · {{limit===0?'每日出图不限次数':'每日最多 '+limit+' 次'}}</small></div><button @click="editing=!editing;key=''">{{enabled?'管理图像通道':'配置图像通道'}}</button></div><div v-if="hasKey" class="actions"><button :disabled="busy" @click="toggle">{{enabled?'停用自动场景出图':'启用自动场景出图'}}</button></div><p v-if="error&&!editing" class="error" role="alert">{{error}}</p><form v-if="editing" @submit.prevent="save"><label><KeyRound :size="15"/> API Key<input v-model="key" type="password" autocomplete="off" :required="!hasKey" placeholder="留空保留当前密钥" minlength="20" maxlength="500"></label><label>每日出图次数（0 为不限）<input v-model.number="limit" type="number" min="0" max="2147483647" required></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="busy||(!hasKey&&key.length<20)||!!key&&key.length<20">保存图像通道</button></form></article></template>
<style scoped>.scene-model-settings h2{display:flex;align-items:center;gap:8px}.scene-model-settings form{max-width:460px;margin-top:20px}</style>
